1	import {
2	  appendTransition,
3	  ensureWorkflowRoot,
4	  listRunIds,
5	  loadWorkflow,
6	  readCheckpoint,
7	  readCurrent,
8	  writeCheckpoint,
9	  writeCurrent,
10	  writeNodeOutput,
11	} from './storage.js';
12	import {
13	  RipplegraphError,
14	  type Checkpoint,
15	  type Edge,
16	  type Graph,
17	  type JsonSchema,
18	  type Node,
19	  type Position,
20	  type TransitionLogEntry,
21	  type Workflow,
22	} from './schema.js';
23	
24	export interface WorkflowRootOptions {
25	  workflowRoot: string;
26	}
27	
28	export interface StartRunOptions extends WorkflowRootOptions {
29	  graph: string;
30	  runId: string;
31	}
32	
33	export interface StepRunOptions extends WorkflowRootOptions {
34	  output: unknown;
35	}
36	
37	export interface SuspendRunOptions extends WorkflowRootOptions {
38	  note?: string;
39	}
40	
41	export interface ResumeRunOptions extends WorkflowRootOptions {
42	  runId: string;
43	}
44	
45	export interface AbandonRunOptions extends WorkflowRootOptions {
46	  reason?: string;
47	}
48	
49	export interface StateOk {
50	  status: 'ok';
51	  workflow: { id: string; version: string };
52	  run: { id: string; status: Checkpoint['status']; rootGraph: string };
53	  position: Position;
54	  node: {
55	    id: string;
56	    purpose: string;
57	    instructions?: string;
58	    exec: Node['exec'];
59	    outputSchema: JsonSchema;
60	  };
61	  context: {
62	    previous: Array<{ id: string; purpose: string }>;
63	    next: Array<{ id: string; purpose: string }>;
64	    latches: [];
65	    capabilities: [];
66	  };
67	  responseContract: { command: 'step'; acceptedFormats: ['json'] };
68	}
69	
70	export interface StateNoFocusedRun {
71	  status: 'no_focused_run';
72	  workflow: { id: string; version: string };
73	  availableGraphs: string[];
74	  resumableRuns: Array<{ id: string; status: 'suspended'; rootGraph: string }>;
75	}
76	
77	export interface RunSummary {
78	  id: string;
79	  status: Checkpoint['status'];
80	  rootGraph: string;
81	  position: Position;
82	  updatedAt: string;
83	}
84	
85	export interface RunList {
86	  status: 'ok';
87	  workflow: { id: string; version: string };
88	  focusedRunId: string | null;
89	  runs: RunSummary[];
90	}
91	
92	export interface ValidationErrorResponse {
93	  status: 'validation_error';
94	  run: { id: string; status: Checkpoint['status']; rootGraph: string };
95	  position: Position;
96	  errors: Array<{ path: string; message: string }>;
97	}
98	
99	export type CoachState = StateOk | StateNoFocusedRun;
100	export type StepRunResponse = StateOk | { status: 'completed'; run: { id: string; status: 'completed'; rootGraph: string }; position: Position } | ValidationErrorResponse;
101	
102	export function validateWorkflowRoot(rootPath: string): { status: 'ok'; workflow: { id: string; version: string }; graphs: string[] } {
103	  const workflow = loadWorkflow(rootPath);
104	  ensureWorkflowRoot(rootPath);
105	  return { status: 'ok', workflow: { id: workflow.id, version: workflow.version }, graphs: Object.keys(workflow.graphs) };
106	}
107	
108	export function startRun(opts: StartRunOptions): StateOk {
109	  const workflow = loadWorkflow(opts.workflowRoot);
110	  ensureWorkflowRoot(opts.workflowRoot);
111	  const current = readCurrent(opts.workflowRoot);
112	  if (current.focusedRunId) {
113	    throw new RipplegraphError('E_FOCUSED_RUN_EXISTS', `focused run already exists: ${current.focusedRunId}`);
114	  }
115	  const graph = getGraph(workflow, opts.graph);
116	  if (listRunIds(opts.workflowRoot).includes(opts.runId)) {
117	    throw new RipplegraphError('E_RUN_EXISTS', `run already exists: ${opts.runId}`);
118	  }
119	  const now = new Date().toISOString();
120	  const checkpoint: Checkpoint = {
121	    runId: opts.runId,
122	    status: 'active',
123	    rootGraph: opts.graph,
124	    workflow: { id: workflow.id, version: workflow.version },
125	    position: { graph: opts.graph, node: graph.entry },
126	    createdAt: now,
127	    updatedAt: now,
128	    outputs: {},
129	  };
130	  writeCheckpoint(opts.workflowRoot, checkpoint);
131	  writeCurrent(opts.workflowRoot, { focusedRunId: opts.runId });
132	  appendTransition(opts.workflowRoot, opts.runId, transitionEntry('start', opts.runId, null, checkpoint.position));
133	  return stateForCheckpoint(workflow, checkpoint);
134	}
135	
136	export function getState(opts: WorkflowRootOptions): CoachState {
137	  const workflow = loadWorkflow(opts.workflowRoot);
138	  ensureWorkflowRoot(opts.workflowRoot);
139	  const current = readCurrent(opts.workflowRoot);
140	  if (!current.focusedRunId) {
141	    return {
142	      status: 'no_focused_run',
143	      workflow: { id: workflow.id, version: workflow.version },
144	      availableGraphs: Object.keys(workflow.graphs),
145	      resumableRuns: resumableRuns(opts.workflowRoot),
146	    };
147	  }
148	  return stateForCheckpoint(workflow, readCheckpoint(opts.workflowRoot, current.focusedRunId));
149	}
150	
151	export function listRuns(opts: WorkflowRootOptions): RunList {
152	  const workflow = loadWorkflow(opts.workflowRoot);
153	  ensureWorkflowRoot(opts.workflowRoot);
154	  const current = readCurrent(opts.workflowRoot);
155	  return {
156	    status: 'ok',
157	    workflow: { id: workflow.id, version: workflow.version },
158	    focusedRunId: current.focusedRunId,
159	    runs: listRunIds(opts.workflowRoot).map((runId) => {
160	      const checkpoint = readCheckpoint(opts.workflowRoot, runId);
161	      return {
162	        id: checkpoint.runId,
163	        status: checkpoint.status,
164	        rootGraph: checkpoint.rootGraph,
165	        position: checkpoint.position,
166	        updatedAt: checkpoint.updatedAt,
167	      };
168	    }),
169	  };
170	}
171	
172	export function stepRun(opts: StepRunOptions): StepRunResponse {
173	  const workflow = loadWorkflow(opts.workflowRoot);
174	  const checkpoint = focusedCheckpoint(opts.workflowRoot);
175	  if (checkpoint.status !== 'active') {
176	    throw new RipplegraphError('E_RUN_NOT_ACTIVE', `focused run is not active: ${checkpoint.status}`);
177	  }
178	  const graph = getGraph(workflow, checkpoint.rootGraph);
179	  const node = getNode(graph, checkpoint.position.node);
180	  if (node.terminal) {
181	    return completeRun(opts.workflowRoot, checkpoint, checkpoint.position);
182	  }
183	  const errors = validateOutput(node.outputSchema, opts.output);
184	  if (errors.length > 0) {
185	    appendTransition(opts.workflowRoot, checkpoint.runId, {
186	      ...transitionEntry('step', checkpoint.runId, checkpoint.position, checkpoint.position),
187	      validation: { ok: false, errors },
188	      error: { code: 'E_VALIDATION', message: 'output failed validation' },
189	    });
190	    return {
191	      status: 'validation_error',
192	      run: { id: checkpoint.runId, status: checkpoint.status, rootGraph: checkpoint.rootGraph },
193	      position: checkpoint.position,
194	      errors,
195	    };
196	  }
197	
198	  const artifact = writeNodeOutput(opts.workflowRoot, checkpoint.runId, checkpoint.position.node, opts.output);
199	  const nextNodeId = selectEdge(node.edges, opts.output)?.to;
200	  if (!nextNodeId) {
201	    throw new RipplegraphError('E_NO_EDGE', `node ${checkpoint.position.node} has no matching edge`);
202	  }
203	  const from = checkpoint.position;
204	  const to = { graph: checkpoint.rootGraph, node: nextNodeId };
205	  checkpoint.outputs[checkpoint.position.node] = opts.output;
206	  checkpoint.position = to;
207	  checkpoint.updatedAt = new Date().toISOString();
208	  appendTransition(opts.workflowRoot, checkpoint.runId, {
209	    ...transitionEntry('step', checkpoint.runId, from, to),
210	    input: { artifact },
211	    output: { artifact },
212	  });
213	  const nextNode = getNode(graph, nextNodeId);
214	  if (nextNode.terminal) {
215	    return completeRun(opts.workflowRoot, checkpoint, to);
216	  }
217	  writeCheckpoint(opts.workflowRoot, checkpoint);
218	  return stateForCheckpoint(workflow, checkpoint);
219	}
220	
221	export function suspendRun(opts: SuspendRunOptions): StateOk {
222	  const workflow = loadWorkflow(opts.workflowRoot);
223	  const checkpoint = focusedCheckpoint(opts.workflowRoot);
224	  if (checkpoint.status !== 'active') {
225	    throw new RipplegraphError('E_RUN_NOT_ACTIVE', `focused run is not active: ${checkpoint.status}`);
226	  }
227	  checkpoint.status = 'suspended';
228	  checkpoint.updatedAt = new Date().toISOString();
229	  if (opts.note) checkpoint.resumeNote = opts.note;
230	  writeCheckpoint(opts.workflowRoot, checkpoint);
231	  writeCurrent(opts.workflowRoot, { focusedRunId: null });
232	  appendTransition(opts.workflowRoot, checkpoint.runId, {
233	    ...transitionEntry('suspend', checkpoint.runId, checkpoint.position, checkpoint.position),
234	    reason: opts.note ?? null,
235	  });
236	  return stateForCheckpoint(workflow, checkpoint);
237	}
238	
239	export function resumeRun(opts: ResumeRunOptions): StateOk {
240	  const workflow = loadWorkflow(opts.workflowRoot);
241	  ensureWorkflowRoot(opts.workflowRoot);
242	  const current = readCurrent(opts.workflowRoot);
243	  if (current.focusedRunId) {
244	    throw new RipplegraphError('E_FOCUSED_RUN_EXISTS', `focused run already exists: ${current.focusedRunId}`);
245	  }
246	  const checkpoint = readCheckpoint(opts.workflowRoot, opts.runId);
247	  if (checkpoint.status !== 'suspended') {
248	    throw new RipplegraphError('E_RUN_NOT_RESUMABLE', `run ${opts.runId} is not suspended`);
249	  }
250	  checkpoint.status = 'active';
251	  checkpoint.updatedAt = new Date().toISOString();
252	  writeCheckpoint(opts.workflowRoot, checkpoint);
253	  writeCurrent(opts.workflowRoot, { focusedRunId: opts.runId });
254	  appendTransition(opts.workflowRoot, checkpoint.runId, transitionEntry('resume', checkpoint.runId, checkpoint.position, checkpoint.position));
255	  return stateForCheckpoint(workflow, checkpoint);
256	}
257	
258	export function abandonRun(opts: AbandonRunOptions): { status: 'abandoned'; run: { id: string; status: 'abandoned'; rootGraph: string }; position: Position } {
259	  const checkpoint = focusedCheckpoint(opts.workflowRoot);
260	  checkpoint.status = 'abandoned';
261	  checkpoint.updatedAt = new Date().toISOString();
262	  writeCheckpoint(opts.workflowRoot, checkpoint);
263	  writeCurrent(opts.workflowRoot, { focusedRunId: null });
264	  appendTransition(opts.workflowRoot, checkpoint.runId, {
265	    ...transitionEntry('abandon', checkpoint.runId, checkpoint.position, checkpoint.position),
266	    reason: opts.reason ?? null,
267	  });
268	  return {
269	    status: 'abandoned',
270	    run: { id: checkpoint.runId, status: 'abandoned', rootGraph: checkpoint.rootGraph },
271	    position: checkpoint.position,
272	  };
273	}
274	
275	function focusedCheckpoint(rootPath: string): Checkpoint {
276	  ensureWorkflowRoot(rootPath);
277	  const current = readCurrent(rootPath);
278	  if (!current.focusedRunId) {
279	    throw new RipplegraphError('E_NO_FOCUSED_RUN', 'no focused run');
280	  }
281	  return readCheckpoint(rootPath, current.focusedRunId);
282	}
283	
284	function completeRun(rootPath: string, checkpoint: Checkpoint, to: Position): StepRunResponse {
285	  checkpoint.status = 'completed';
286	  checkpoint.position = to;
287	  checkpoint.updatedAt = new Date().toISOString();
288	  writeCheckpoint(rootPath, checkpoint);
289	  writeCurrent(rootPath, { focusedRunId: null });
290	  return {
291	    status: 'completed',
292	    run: { id: checkpoint.runId, status: 'completed', rootGraph: checkpoint.rootGraph },
293	    position: checkpoint.position,
294	  };
295	}
296	
297	function stateForCheckpoint(workflow: Workflow, checkpoint: Checkpoint): StateOk {
298	  const graph = getGraph(workflow, checkpoint.rootGraph);
299	  const node = getNode(graph, checkpoint.position.node);
300	  return {
301	    status: 'ok',
302	    workflow: { id: workflow.id, version: workflow.version },
303	    run: { id: checkpoint.runId, status: checkpoint.status, rootGraph: checkpoint.rootGraph },
304	    position: checkpoint.position,
305	    node: {
306	      id: checkpoint.position.node,
307	      purpose: node.purpose,
308	      instructions: node.instructions,
309	      exec: node.exec,
310	      outputSchema: node.outputSchema,
311	    },
312	    context: {
313	      previous: previousNodes(checkpoint),
314	      next: node.edges.map((edge) => {
315	        const next = getNode(graph, edge.to);
316	        return { id: edge.to, purpose: next.purpose };
317	      }),
318	      latches: [],
319	      capabilities: [],
320	    },
321	    responseContract: { command: 'step', acceptedFormats: ['json'] },
322	  };
323	}
324	
325	function getGraph(workflow: Workflow, graphId: string): Graph {
326	  const graph = workflow.graphs[graphId];
327	  if (!graph) throw new RipplegraphError('E_UNKNOWN_GRAPH', `unknown graph: ${graphId}`);
328	  return graph;
329	}
330	
331	function getNode(graph: Graph, nodeId: string): Node {
332	  const node = graph.nodes[nodeId];
333	  if (!node) throw new RipplegraphError('E_UNKNOWN_NODE', `unknown node: ${nodeId}`);
334	  return node;
335	}
336	
337	function selectEdge(edges: Edge[], output: unknown): Edge | null {
338	  return edges.find((edge) => !edge.when || matchesWhen(edge.when, output)) ?? null;
339	}
340	
341	function matchesWhen(when: Record<string, unknown>, output: unknown): boolean {
342	  if (!output || typeof output !== 'object' || Array.isArray(output)) return false;
343	  const record = output as Record<string, unknown>;
344	  return Object.entries(when).every(([key, value]) => record[key] === value);
345	}
346	
347	function validateOutput(schema: JsonSchema, output: unknown): Array<{ path: string; message: string }> {
348	  const errors: Array<{ path: string; message: string }> = [];
349	  validateValue(schema, output, '', errors);
350	  return errors;
351	}
352	
353	function validateValue(schema: JsonSchema, value: unknown, path: string, errors: Array<{ path: string; message: string }>): void {
354	  if (schema.type && !matchesType(schema.type, value)) {
355	    errors.push({ path, message: `expected ${schema.type}` });
356	    return;
357	  }
358	  if (schema.enum && !schema.enum.some((item) => item === value)) {
359	    errors.push({ path, message: `expected one of ${schema.enum.join(', ')}` });
360	  }
361	  if (schema.type === 'object' || schema.properties || schema.required) {
362	    if (!value || typeof value !== 'object' || Array.isArray(value)) {
363	      errors.push({ path, message: 'expected object' });
364	      return;
365	    }
366	    const record = value as Record<string, unknown>;
367	    for (const key of schema.required ?? []) {
368	      if (!(key in record)) errors.push({ path: path ? `${path}.${key}` : key, message: 'required' });
369	    }
370	    for (const [key, childSchema] of Object.entries(schema.properties ?? {})) {
371	      if (key in record) validateValue(childSchema, record[key], path ? `${path}.${key}` : key, errors);
372	    }
373	  }
374	}
375	
376	function matchesType(type: JsonSchema['type'], value: unknown): boolean {
377	  if (type === 'array') return Array.isArray(value);
378	  if (type === 'object') return Boolean(value) && typeof value === 'object' && !Array.isArray(value);
379	  return typeof value === type;
380	}
381	
382	function previousNodes(checkpoint: Checkpoint): Array<{ id: string; purpose: string }> {
383	  return Object.keys(checkpoint.outputs).slice(-2).map((id) => ({ id, purpose: 'Completed node' }));
384	}
385	
386	function resumableRuns(rootPath: string): StateNoFocusedRun['resumableRuns'] {
387	  return listRunIds(rootPath)
388	    .map((runId) => readCheckpoint(rootPath, runId))
389	    .filter((checkpoint) => checkpoint.status === 'suspended')
390	    .map((checkpoint) => ({ id: checkpoint.runId, status: 'suspended', rootGraph: checkpoint.rootGraph }));
391	}
392	
393	function transitionEntry(
394	  op: TransitionLogEntry['op'],
395	  runId: string,
396	  from: Position | null,
397	  to: Position | null,
398	): TransitionLogEntry {
399	  return {
400	    ts: new Date().toISOString(),
401	    op,
402	    runId,
403	    from,
404	    to,
405	    actor: 'agent',
406	    input: null,
407	    output: null,
408	    validation: { ok: true },
409	    gateDecision: null,
410	    reason: null,
411	    error: null,
412	  };
413	}
414

