14	
15	function workflowPath(rootPath: string): string {
16	  return path.join(rootPath, 'workflow.json');
17	}
18	
19	export function stateDir(rootPath: string): string {
20	  return path.join(rootPath, '.ripplegraph');
21	}
22	
23	export function runsDir(rootPath: string): string {
24	  return path.join(stateDir(rootPath), 'runs');
25	}
26	
27	export function currentPath(rootPath: string): string {
28	  return path.join(stateDir(rootPath), 'current.json');
29	}
30	
31	export function runDir(rootPath: string, runId: string): string {
32	  assertPathSegment(runId, 'runId');
33	  return path.join(runsDir(rootPath), runId);
34	}
35	
36	export function checkpointPath(rootPath: string, runId: string): string {
37	  return path.join(runDir(rootPath, runId), 'checkpoint.json');
38	}
39	
40	export function transitionLogPath(rootPath: string, runId: string): string {
41	  return path.join(runDir(rootPath, runId), 'transition-log.jsonl');
42	}
43	
44	export function artifactPath(rootPath: string, runId: string, nodeId: string): string {
45	  assertPathSegment(nodeId, 'nodeId');
46	  return path.join(runDir(rootPath, runId), 'artifacts', nodeId, 'output.json');
47	}
48	
49	function assertPathSegment(value: string, label: string): void {
50	  if (!value || value.includes('/') || value.includes('\\') || value === '.' || value === '..') {
51	    throw new RipplegraphError('E_BAD_PATH_SEGMENT', `${label} must be a filesystem-safe path segment`);
52	  }
53	}
54	
55	function readJson(filePath: string): unknown {
56	  try {
57	    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
58	  } catch (error) {
59	    throw new RipplegraphError('E_BAD_JSON', `failed to read JSON at ${filePath}: ${(error as Error).message}`);
60	  }
61	}
62	
63	function writeJson(filePath: string, payload: unknown): void {
64	  fs.mkdirSync(path.dirname(filePath), { recursive: true });
65	  const tmp = `${filePath}.tmp.${process.pid}.${Date.now()}`;
66	  fs.writeFileSync(tmp, JSON.stringify(payload, null, 2), 'utf8');
67	  fs.renameSync(tmp, filePath);
68	}
69	
70	export function ensureWorkflowRoot(rootPath: string): void {
71	  fs.mkdirSync(runsDir(rootPath), { recursive: true });
72	  if (!fs.existsSync(currentPath(rootPath))) {
73	    writeCurrent(rootPath, { focusedRunId: null });
74	  }
75	}
76	
77	export function loadWorkflow(rootPath: string): Workflow {
78	  const filePath = workflowPath(rootPath);
79	  if (!fs.existsSync(filePath)) {
80	    throw new RipplegraphError('E_MISSING_WORKFLOW', `no workflow.json found at ${rootPath}`);
81	  }
82	  const result = workflowSchema.safeParse(readJson(filePath));
83	  if (!result.success) {
84	    throw new RipplegraphError(
85	      'E_INVALID_WORKFLOW',
86	      result.error.issues.map((issue) => `${issue.path.join('.') || '<root>'}: ${issue.message}`).join('; '),
87	    );
88	  }
89	  return result.data;
90	}
91	
92	export function readCurrent(rootPath: string): Current {
93	  const filePath = currentPath(rootPath);
94	  if (!fs.existsSync(filePath)) return { focusedRunId: null };
95	  const result = currentSchema.safeParse(readJson(filePath));
96	  if (!result.success) {
97	    throw new RipplegraphError(
98	      'E_INVALID_CURRENT',
99	      result.error.issues.map((issue) => `${issue.path.join('.') || '<root>'}: ${issue.message}`).join('; '),
100	    );
101	  }
102	  return result.data;
103	}
104	
105	export function writeCurrent(rootPath: string, current: Current): void {
106	  writeJson(currentPath(rootPath), currentSchema.parse(current));
107	}
108	
109	export function readCheckpoint(rootPath: string, runId: string): Checkpoint {
110	  const filePath = checkpointPath(rootPath, runId);
111	  if (!fs.existsSync(filePath)) {
112	    throw new RipplegraphError('E_MISSING_CHECKPOINT', `no checkpoint.json found for run ${runId}`);
113	  }
114	  const result = checkpointSchema.safeParse(readJson(filePath));
115	  if (!result.success) {
116	    throw new RipplegraphError(
117	      'E_INVALID_CHECKPOINT',
118	      result.error.issues.map((issue) => `${issue.path.join('.') || '<root>'}: ${issue.message}`).join('; '),
119	    );
120	  }
121	  return result.data;
122	}
123	
124	export function writeCheckpoint(rootPath: string, checkpoint: Checkpoint): void {
125	  const runPath = runDir(rootPath, checkpoint.runId);
126	  fs.mkdirSync(path.join(runPath, 'artifacts'), { recursive: true });
127	  fs.mkdirSync(path.join(runPath, 'scratch'), { recursive: true });
128	  writeJson(checkpointPath(rootPath, checkpoint.runId), checkpointSchema.parse(checkpoint));
129	}
130	
131	export function writeNodeOutput(rootPath: string, runId: string, nodeId: string, output: unknown): string {
132	  const filePath = artifactPath(rootPath, runId, nodeId);
133	  writeJson(filePath, output);
134	  return path.relative(runDir(rootPath, runId), filePath).replaceAll(path.sep, '/');
135	}
136	
137	export function appendTransition(rootPath: string, runId: string, entry: TransitionLogEntry): void {
138	  const parsed = transitionLogEntrySchema.parse(entry);
139	  const filePath = transitionLogPath(rootPath, runId);
140	  fs.mkdirSync(path.dirname(filePath), { recursive: true });
141	  fs.appendFileSync(filePath, `${JSON.stringify(parsed)}\n`, 'utf8');
142	}
143	
144	export function listRunIds(rootPath: string): string[] {
145	  const dir = runsDir(rootPath);
146	  if (!fs.existsSync(dir)) return [];
147	  return fs
148	    .readdirSync(dir, { withFileTypes: true })
149	    .filter((entry) => entry.isDirectory())
150	    .map((entry) => entry.name)
151	    .sort();
152	}
